                st.lastParserCmd = cmd;
                return contractOut;
            }
            if (/bash .*threads /.test(cmd)) {
                st.commands.push(cmd);
                st.lastThreadsCmd = cmd;
                return threadsOut !== undefined ? threadsOut : 'thread summary line\n';
            }
            return orig(cmd);
        };
    })(st.exec);
    return st;
}

