    if (fx.graphqlFails) fs.writeFileSync(path.join(dir, 'graphql_fails'), 'x\n');
    fs.writeFileSync(path.join(dir, 'threads.json'), JSON.stringify(fx.threads || {
        data: { repository: { pullRequest: { reviewThreads: { nodes: [] } } } }
    }) + '\n');
