    '  prev="$a"',
    'done',
    '{ printf \'gh\'; for a in "$@"; do printf \' [%s]\' "$a"; done; printf \'\\n\'; } >> "$SCENARIO_DIR/gh_calls.log"',
    'apply_jq() { if [ -n "$JQ" ]; then jq "$JQ"; else cat; fi; }',
