}

// the entry's unwrap (execOut pattern, no trim — body fidelity)
function unwrap(res) {
    return String((res && (res.output || res.stdout)) || res || '');
}

var NOW_MS = Date.UTC(2026, 10, 13, 12, 34, 56);
var STUB_DIR = '/tmp/awf-stub';
