        (result.pr ? ' (PR #' + result.pr + ')' : '') +
        (result.decision ? ' — ' + result.decision : ''));
    return result;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue
    };
}

