 */
function execStub(rules) {
    var st = { commands: [], bodies: [], thrown: 0 };
    st.exec = function (cmd) {
        cmd = String(cmd);
        st.commands.push(cmd);
        for (var i = 0; i < rules.length; i++) {
            if (new RegExp(rules[i][0]).test(cmd)) {
