        tempFile: function (hint) { return '/tmp/rv-' + hint; },
        clock: over.clock || function () { return new Date(NOW_MS); },
        sleepMs: over.sleepMs || function (ms) { io.sleeps.push(ms); },
        log: function (line) { io.logs.push(line); }
