        fs.chmodSync(path.join(bin, n), 0o755);
    });
    fs.writeFileSync(path.join(dir, 'issue_result.txt'), fx.jobResult);
    fs.writeFileSync(path.join(dir, 'pr_view.json'), JSON.stringify(fx.prView || {
